import type { Register } from 'claude-code'

// Factors from claude-carbon (data/factors.json, METHODOLOGY.md): Jegham et al. 2025,
// gCO2e per million tokens, location-based (AWS CIF 0.287 g/Wh, PUE 1.14 included).
const G_PER_MTOK: Record<string, [number, number]> = {
  fable: [156, 3304],
  opus: [78, 1652],
  sonnet: [39, 826],
  haiku: [20, 413],
}
const CACHE_READ = 0.08 // cache-read token = 8% of an uncached input token
const G_CO2_PER_WH = 0.287
const ML_PER_WH = 0.18 + 5.11 // WUE on-site + off-site, L/kWh == mL/Wh
// "world" equivalences from claude-carbon, plus a glass of water
const G_PER_KM = 200, G_PER_CHARGE = 8.7, ML_GLASS = 250

const family = (m: string) => /fable|mythos/.test(m) ? 'fable' : /opus/.test(m) ? 'opus' : /haiku/.test(m) ? 'haiku' : 'sonnet'
const f = (n: number) => (n < 10 ? n.toFixed(2) : n.toFixed(0))
const day = (ms: number) => { const d = new Date(ms); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}` }

const metres = (m: number) => (m < 1000 ? `${f(m)} m` : `${(m / 1000).toFixed(1)} km`)
// everyday comparisons for g CO2 (water derived from it)
const eq = (g: number) => {
  const ml = (g / G_CO2_PER_WH) * ML_PER_WH
  return `🚗 ${metres(g / G_PER_KM * 1000)} · 📱 ${(g / G_PER_CHARGE).toFixed(1)} charges · 🥛 ${(ml / ML_GLASS).toFixed(1)} glasses`
}
const row = (label: string, g: number) => {
  const wh = g / G_CO2_PER_WH
  return `${label.padEnd(10)} ${f(g).padStart(7)} g ${f(wh * ML_PER_WH).padStart(7)} mL ${f(wh).padStart(6)} Wh  ≈ ${eq(g)}`
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'eco', description: 'Daily and monthly CO₂ / water / energy history' })
    return next(e)
  })

  on('command.run', { command: 'eco' }, async $ => {
    const days = ((await $.store.get('days')) ?? {}) as Record<string, number>
    const keys = Object.keys(days).sort()
    if (!keys.length) return { text: 'No history yet: it fills in after your first completed turn.' }
    const months: Record<string, number> = {}
    for (const k of keys) months[k.slice(0, 7)] = (months[k.slice(0, 7)] ?? 0) + days[k]
    const lines = [
      'Last 30 days (estimates, see README):',
      ...keys.slice(-30).map(k => row(k, days[k])),
      '',
      'By month:',
      ...Object.keys(months).sort().slice(-12).map(k => row(k, months[k])),
    ]
    return { text: lines.join('\n') }
  })

  let co2 = 0 // session total; resets on reload/restart
  on('turn.complete', async ($, e, next) => {
    const r = await next(e)
    const u = r.usage
    if (u && u.model.includes('claude')) {
      const [i, o] = G_PER_MTOK[family(u.model)]
      const g = ((u.input_tokens + u.cache_creation_input_tokens + u.cache_read_input_tokens * CACHE_READ) * i + u.output_tokens * o) / 1e6
      co2 += g
      // daily history in $.store (key "days": { "YYYY-MM-DD": gCO2 }), kept ~13 months
      const today = day(await $.clock.now())
      const days = ((await $.store.get('days')) ?? {}) as Record<string, number>
      days[today] = (days[today] ?? 0) + g
      for (const k of Object.keys(days).sort().slice(0, -400)) delete days[k]
      await $.store.set('days', days)

      const wh = co2 / G_CO2_PER_WH, ml = wh * ML_PER_WH
      $.ui.status(`🌍 ~${f(co2)} g CO₂ · 💧 ~${f(ml)} mL · ⚡ ${f(wh)} Wh (≈ ${eq(co2)})`)
    }
    return r
  })
}

